1. Rename batch producer to sequencer
2. Filter deposits, withdrawals and reimbursements based on PRD requirement: fewer than 6 confirmations for `Complete`, `Cancelled` or `Failed`.
3. Filter out claims that are `NotStarted`.
4. Fix multiple claim txids. Skip those not found in Esplora.
5. Use `uptime` to get `Online` and `Offline` status of bridge operators.

Tested the operator pk and rpc urls match with this test.
```
#[cfg(test)]
mod tests {
    use crate::config::BridgeMonitoringConfig;
    use crate::utils::create_rpc_client;
    use jsonrpsee::core::client::ClientT;
    use strata_bridge_rpc::types::RpcOperatorStatus;

    #[tokio::test]
    async fn test_operator_returns_offline_for_self() {
        let config = BridgeMonitoringConfig::new();

        for (pk, rpc_url) in config.bridge_rpc_urls() {
            let rpc_client = create_rpc_client(rpc_url);

            let status_result = rpc_client
                .request::<RpcOperatorStatus, _>("stratabridge_operatorStatus", (pk.clone(),))
                .await;

            assert!(
                status_result.is_ok(),
                "RPC call to {rpc_url} failed for pk {pk}",
            );

            let status = status_result.unwrap();
            assert!(
                matches!(status, RpcOperatorStatus::Offline),
                "Expected `Offline` for self-query to {rpc_url} with pk {pk}, got {status:?}",
            );
        }
    }
}
```

